import type { Address, Hex } from 'viem';
export type VerifyResult = {
    ok: true;
    from: Address;
    /**
     * Releases this payment's nonce claim in the replay store, making the
     * authorization usable again. Call it when the request fails AFTER
     * verification but BEFORE any settlement is broadcast — a KYC refusal,
     * a quota rejection, a handler that threw — so an honest payer is not
     * locked out of their own signed authorization for the claim's TTL.
     *
     * Do NOT call it once a settle transaction has been sent: the outcome
     * is then unknown, and leaving the claim in place is the conservative
     * choice. Safe to call when no store is configured (no-op), and safe
     * to call more than once.
     */
    releaseNonce: () => Promise<void>;
} | {
    ok: false;
    reason: VerifyFailureReason;
    detail?: string;
};
export type VerifyFailureReason = 
/** The payment envelope was structurally unusable — see the note in verify.ts. */
'malformed_payload' | 'scheme_mismatch' | 'network_mismatch' | 'recipient_mismatch' | 'value_mismatch' | 'asset_mismatch' | 'expired' | 'not_yet_valid' | 'bad_signature' | 'nonce_already_used'
/**
 * The app-level replay guard (NonceStore) already holds a claim on this
 * (network, asset, nonce). Rejected before any chain interaction.
 */
 | 'nonce_already_seen'
/** The optional on-chain nonce pre-check could not be completed. */
 | 'nonce_check_unavailable'
/**
 * The replay guard is holding its maximum of unexpired claims, so it could
 * not take one for this payment. Transient and retryable — NOT a replay, and
 * deliberately distinct from `nonce_check_unavailable`, which is documented
 * as safe to proceed past because settlement reverts on a replayed nonce
 * anyway. Proceeding past THIS one is not safe: it means the replay guard
 * never ran, so two requests could carry the same authorization at once.
 */
 | 'nonce_store_at_capacity' | 'missing_domain_metadata';
export type SettleResult = {
    tx: Hex;
    blockNumber: bigint;
    gasUsed: bigint;
    payer: Address;
    network: string;
};
